-- V76.3 catalog + requirement definitions

on conflict(code) do update set label=excluded.label,category=excluded.category,sensitivity=excluded.sensitivity,extraction_profile=excluded.extraction_profile,description=excluded.description,active=true,updated_at=now();

on conflict(workflow_slug,phase_code,requirement_key,version) do update set document_code=excluded.document_code,requirement_level=excluded.requirement_level,exit_policy=excluded.exit_policy,reason=excluded.reason,condition_definition=excluded.condition_definition,legal_ruleset_key=excluded.legal_ruleset_key,professional_type=excluded.professional_type,active=true,updated_at=now();
